def main():
    sources = json.loads(Path("source.json").read_text())
    assert len(sources) == 12
    assert set(METADATA) == {source["number"] for source in sources}
    result = []
    for source in sources:
        number = source["number"]
        proposed = (Path("drafts") / (number.replace(" ", "_") + ".xml")).read_text().strip()
        result.append({
            **{key: source[key] for key in ("code_id", "source_id", "source_sha256", "number")},
            "proposed_xml": proposed,
            "reason": METADATA[number]["reason"],
            "review_notes": METADATA[number]["review_notes"],
            "status": "rewrite_draft",
        })
    Path("answer.json").write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n")


if __name__ == "__main__":
    main()
